Retrieve Banking products currently publicly available > OpenAPI definition #/components/schemas/AEProductCharges

{
  "description": "Fees and charges applicable to the account or product",
  "type": "array",
  "minItems": 1,
  "items": {
    "description": "Properties of the charges applied",
    "type": "object",
    "required": [
      "Name",
      "Description",
      "Charge"
    ],
    "properties": {
      "Type": {
        "description": "Type of charge.",
        "type": "string",
        "enum": [
          "MonthlyFees",
          "AnnualFees",
          "BalanceFallBelow",
          "Overdraft",
          "DomesticTransaction",
          "ForeignTransaction",
          "ATMWithdrawal",
          "ChequeBook",
          "ReplacementChequeBook",
          "ReturnCheque",
          "CardReplacement",
          "AccountStatement",
          "LetterIssued",
          "AccountClosure",
          "CashAdvance",
          "LatePayment",
          "BalanceTransfer",
          "OverLimit",
          "SalesVoucherCopy",
          "Processing",
          "FinanceCancellation",
          "PartialPayment",
          "EarlySettlement",
          "FinalSettlement",
          "Other"
        ]
      },
      "Name": {
        "type": "string",
        "description": "Name of the charge",
        "minLength": 1,
        "maxLength": 40
      },
      "Description": {
        "description": "Description of the fee, including purpose and applicability",
        "type": "string"
      },
      "Charge": {
        "description": "Array of charge components including amount, currency, and applicable rate",
        "type": "array",
        "items": {
          "$ref": "#/components/schemas/AEProductFinancialCalculationMeasure"
        }
      },
      "Conditions": {
        "description": "Array of conditions that trigger the fee",
        "type": "array",
        "items": {
          "$ref": "#/components/schemas/AEProductConditions"
        }
      },
      "Justification": {
        "description": "Reasoning or business logic behind the imposition of the fee",
        "type": "string"
      },
      "Frequency": {
        "description": "Frequency or trigger logic for the reward or fee, such as monthly if balance < 1000, or periodic  Hibah distribution",
        "type": "string"
      },
      "DonatedToCharity": {
        "description": "Confirmation if the charge will be donated to charity when the product is Sharia compliant",
        "type": "boolean"
      },
      "Notes": {
